 if($('#openMeaningMap'))$('#openMeaningMap').onclick=()=>{const el=$('#prepMeaningMap');el.hidden=!el.hidden;addWordTrace(w,'assistance',{step:'MEANING_MAP',source:'VERIFIED_LANGUAGE_MODEL',stage:'MEMORIZATION',languageDomain:w.languageDomain||'ENGLISH'});save()};
 $('#prepNext').onclick=()=>{addWordTrace(w,'acquisition',{event:'MEMORIZATION_EXPOSURE',sheetId:sh.sheetId,missionRole:role,thinkingTrailUsed:!!thinkingReveal?.disabled,inferenceRecorded:!!traceList(w,'inference').find(x=>x.event==='FIRST_SEEN_PREDICTION'),meaningConfirmed:role!=='NEW'||!thinkingHtml||!!$('#confirmNewMeaning')?.disabled,meaningMapOpened:!$('#prepMeaningMap')?.hidden,sceneShown:!!w.example,sceneText:w.example||'',meaningShown:true,meaningText:w.kor,shapeLength:w.eng.length});if(inferenceWordDomain(w)==='KOREAN'&&w.example)addLanguageMemoryEvidence(w,{axis:'CONTEXT',evidenceType:'CONTEXT_EXPOSURE_ONLY',evidenceMode:'EXPOSURE',stage:'MEMORIZATION',source:'EXAMPLE_CONTEXT',objectiveVerified:false,objectiveRecall:false,recallScoreImpact:false});S.learning.prepIndex++;if(S.learning.prepIndex>=ws.length){S.learning.prepIndex=0;S.learning.prepCompleted=true;S.learning.phase='first';save();renderFirstContact()}else{save();renderMemorizeStage()}};
 setPartner(role==='NEW'?'정답부터 보지 말고, 먼저 네 머릿속에 장면을 만들어보자.':'전에 만든 기억을 짧게 다시 깨워보자.','focus')
